// Relays this peer put in its punch replies, from its `relay-server` option or a rendezvous
// server. A genuine RequestRelay echoes one back; this bounds where a request can send this peer,
// it does not authenticate the request.
static REPORTED_RELAYS: std::sync::Mutex<VecDeque<(String, Instant)>> =
    std::sync::Mutex::new(VecDeque::new());
const MAX_REPORTED_RELAYS: usize = 32;
// Far longer than a controller's direct attempts before it asks for the relay, yet a relay
// dropped from the configuration stops being accepted.
const REPORTED_RELAY_TTL: Duration = Duration::from_secs(600);

fn remember_reported_relay(relay_server: &str, now: Instant) {
    let relay_server = check_port(relay_server, config::RELAY_PORT);
    let mut relays = REPORTED_RELAYS.lock().unwrap();
    relays.retain(|(r, at)| {
        *r != relay_server && now.saturating_duration_since(*at) < REPORTED_RELAY_TTL
    });
    if relays.len() >= MAX_REPORTED_RELAYS {
        relays.pop_front();
    }
    relays.push_back((relay_server, now));
}

fn is_reported_relay(relay_server: &str, now: Instant) -> bool {
    let relay_server = check_port(relay_server, config::RELAY_PORT);
    REPORTED_RELAYS.lock().unwrap().iter().any(|(r, at)| {
        *r == relay_server && now.saturating_duration_since(*at) < REPORTED_RELAY_TTL
    })

const ICE_DEDUP_WINDOW: usize = 256;
/// Answerers between an offer and an open data channel. An offer arrives before any password or
/// accept prompt, and each one builds a peer connection that binds a socket per interface and
/// runs ICE for up to `CONNECT_TIMEOUT`, where a forged TCP punch costs one connect. Past this
/// many the offer is declined, and the controller carries on over punch and relay as it does
/// for a peer without WebRTC. A guard against pathological setup concurrency, above what
/// legitimate controllers reach at once in the seconds ICE takes; once the channel is open the
/// connection is one like any other, and the connection layer bounds unauthenticated
/// connections in number and in time for every transport alike.
const MAX_WEBRTC_ANSWERERS: usize = 16;

[dependencies]
async-trait = "0.1"
scrap = { path = "libs/scrap", features = ["wayland"] }
hbb_common = { path = "libs/hbb_common", features = ["webrtc"] }
base = { path = "libs/base" }
serde_derive = "1.0"
serde = "1.0"

[target.'cfg(not(target_os = "linux"))'.dependencies]
# https://github.com/rustdesk/rustdesk/discussions/10197, not use cpal on linux
cpal = { git = "https://github.com/rustdesk-org/cpal", branch = "osx-screencapturekit" }
ringbuf = "0.3"

[target.'cfg(not(any(target_os = "android", target_os = "ios")))'.dependencies]
mac_address = "1.1"
sciter-rs = { git = "https://github.com/rustdesk-org/rust-sciter", branch = "dyn" }
sys-locale = "0.3"
enigo = { path = "libs/enigo", features = [ "with_serde" ] }
clipboard = { path = "libs/clipboard" }
